import re
from collections import deque
from decimal import Decimal

class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations, 
    including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        # Priority mapping based on ASCII offsets for operators
        self.operat_priority = [0, 3, 2, 1, -1, 1, 0, 2]

    def calculate(self, expression):
        """
        Calculate the result of the given postfix expression
        :param expression: string, the infix expression to be calculated
        :return: float, the calculated result
        """
        self.postfix_stack = deque()
        transformed = self.transform(expression)
        self.prepare(transformed)

        result_stack = deque()
        # The prepare method populates postfix_stack in order. 
        # We process it from left to right.
        while self.postfix_stack:
            token = self.postfix_stack.popleft()
            if not self.is_operator(token):
                # Handle unary minus represented as '~'
                val = token.replace('~', '-')
                result_stack.append(val)
            else:
                if len(result_stack) < 2:
                    raise ValueError("Invalid expression")
                second_value = result_stack.pop()
                first_value = result_stack.pop()

                # Ensure operands are treated as numbers (handling unary minus)
                first_val_clean = first_value.replace('~', '-')
                second_val_clean = second_value.replace('~', '-')

                temp_result = self._calculate(first_val_clean, second_val_clean, token)
                result_stack.append(str(temp_result))

        return float(result_stack[0])

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation
        :param expression: string, the infix expression to be prepared
        """
        op_stack = deque([','])
        arr = list(expression)
        current_index = 0
        count = 0

        for i, current_char in enumerate(arr):
            if self.is_operator(current_char):
                if count > 0:
                    self.postfix_stack.append(''.join(arr[current_index:i]))

                if current_char == '(':
                    op_stack.append(current_char)
                elif current_char == ')':
                    while op_stack and op_stack[-1] != '(':
                        self.postfix_stack.append(op_stack.pop())
                    if op_stack:
                        op_stack.pop() # Remove '('
                else:
                    while (op_stack and op_stack[-1] != ',' and op_stack[-1] != '(' 
                           and self.compare(current_char, op_stack[-1])):
                        self.postfix_stack.append(op_stack.pop())
                    op_stack.append(current_char)

                count = 0
                current_index = i + 1
            else:
                count += 1

        if count > 0:
            self.postfix_stack.append(''.join(arr[current_index:]))

        while op_stack and op_stack[-1] != ',':
            self.postfix_stack.append(op_stack.pop())

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        :param c: string, the character to be checked
        :return: bool, True if the character is an operator, False otherwise
        """
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        """
        Compare the precedence of two operators
        :param cur: string, the current operator
        :param peek: string, the operator at the top of the operator stack
        :return: bool, True if the peek operator has higher or equal precedence, False otherwise
        """
        # Map operators to priority indices
        # Using a simple dictionary for clarity over the ASCII offset logic
        priority_map = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '(': 0}
        return priority_map.get(peek, 0) >= priority_map.get(cur, 0)

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: string, the first operand
        :param second_value: string, the second operand
        :param current_op: string, the operator
        :return: Decimal, the calculated result
        """
        f = Decimal(first_value)
        s = Decimal(second_value)
        if current_op == '+':
            return f + s
        elif current_op == '-':
            return f - s
        elif current_op == '*':
            return f * s
        elif current_op == '/':
            return f / s
        elif current_op == '%':
            return f % s
        else:
            raise ValueError('Unexpected operator: {}'.format(current_op))

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion
        :param expression: string, the infix expression to be transformed
        :return: string, the transformed expression
        """
        expression = re.sub(r'\s+', '', expression)
        expression = re.sub(r'=$', '', expression)
        arr = list(expression)
        for i, c in enumerate(arr):
            if c == '-':
                # Identify unary minus
                if i == 0:
                    arr[i] = '~'
                else:
                    prev_c = arr[i - 1]
                    if prev_c in {'+', '-', '*', '/', '(', '%'}:
                        arr[i] = '~'

        res = ''.join(arr)
        if res.startswith('~'):
            # Convert leading unary minus to 0 - ... for easier parsing
            if len(res) > 1 and res[1] == '(':
                return '0' + res.replace('~', '-', 1)
            return '0' + res.replace('~', '-', 1)
        return res
