    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        """
        if not isinstance(data, (list, tuple)):
            raise Exception('the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple')

        if len(data) == 0:
            return (0.0, [0.0])

        # Handle single tuple case: ([1, 0, ...], 5)
        if isinstance(data, tuple) and len(data) == 2 and isinstance(data[0], (list, tuple, np.ndarray)):
            sub_list, total_num = data
            if total_num == 0:
                mr = 0.0
            else:
                mr = 0.0
                for i, val in enumerate(sub_list):
                    if val == 1:
                        mr = 1.0 / (i + 1)
                        break
            return (mr, [mr])

        # Handle list of tuples case: [([1, 0, ...], 5), ...]
        if isinstance(data, list):
            separate_result = []
            for item in data:
                sub_list, total_num = item
                if total_num == 0:
                    mr = 0.0
                else:
                    mr = 0.0
                    for i, val in enumerate(sub_list):
                        if val == 1:
                            mr = 1.0 / (i + 1)
                            break
                separate_result.append(mr)
            return (float(np.mean(separate_result)), separate_result)

        raise Exception('Invalid input format')

    @staticmethod
    def map(data):
        """
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        """
        if not isinstance(data, (list, tuple)):
            raise Exception('the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple')

        if len(data) == 0:
            return (0.0, [0.0])

        def calculate_ap(sub_list, total_num):
            if total_num == 0:
                return 0.0
            ap = 0.0
            hits = 0
            for i, val in enumerate(sub_list):
                if val == 1:
                    hits += 1
                    ap += hits / (i + 1)
            return ap / total_num

        # Handle single tuple case: ([1, 0, ...], 5)
        if isinstance(data, tuple) and len(data) == 2 and isinstance(data[0], (list, tuple, np.ndarray)):
            sub_list, total_num = data
            ap = calculate_ap(sub_list, total_num)
            return (ap, [ap])

        # Handle list of tuples case: [([1, 0, ...], 5), ...]
        if isinstance(data, list):
            separate_result = []
            for item in data:
                sub_list, total_num = item
                ap = calculate_ap(sub_list, total_num)
                separate_result.append(ap)
            return (float(np.mean(separate_result)), separate_result)

        raise Exception('Invalid input format')
